// 24-S4 acceptance: catching up a tab's confirmed state with operations
// committed elsewhere (`applyCommitted`, `applySnapshot`), an acceptance
// that lands ahead of the confirmed version (`settle`), and a randomized
// convergence of several tabs that poll. Pure. Do not edit this file to
// match an implementation.
import { describe, expect, it } from 'vitest';
import { createGrid, withLetter, type Grid } from '@/engine/grid';
import { serializeGrid } from '@/lib/puzzle-storage';
import { applyOperation, epochAfter, evaluateOperation, type PuzzleContent, type PuzzleState } from './apply';
import type { CommittedOperation } from './catchup';
import type { Operation, OperationBody } from './operation';
import {
  applyCommitted, applySnapshot, cellWrites, enqueue, makeOperation, projectOutbox, rebaseView, settle, type Outbox,
} from './outbox';

function letters(grid: Grid, entries: Array<[number, number, string]>): Grid {
  return entries.reduce((next, [col, row, letter]) => withLetter(next, { col, row }, letter), grid);
}
const blank = createGrid({ cols: 5, rows: 5 });
const cat = letters(blank, [[0, 0, 'C'], [1, 0, 'A'], [2, 0, 'T']]);
const content = (grid: Grid, extra: Partial<PuzzleContent> = {}): PuzzleContent => ({
  grid: serializeGrid(grid), hints: {}, title: 'Mini', phase: 'grid', ...extra,
});
const outbox = (base: PuzzleContent = content(cat), version = 4, resetEpoch = 0): Outbox => ({
  confirmed: { content: base, version, resetEpoch }, pending: [],
});
let counter = 0;
const add = (box: Outbox, body: OperationBody, clientId = 'tab'): [Outbox, Operation] => {
  const op = makeOperation(box, body, { opId: `op-${++counter}`, puzzleId: 'p', clientId });
  return [enqueue(box, op), op];
};
/** An operation committed elsewhere as `version`. */
const remote = (body: OperationBody, version: number, epoch = 0): CommittedOperation => ({
  ...body, opId: `remote-${++counter}`, puzzleId: 'p', clientId: 'other', epoch, baseVersion: version - 1, version,
} as CommittedOperation);
const write = (col: number, row: number, value: string | null): OperationBody =>
  ({ kind: 'cells', writes: [{ col, row, value }] });
const letterAt = (c: PuzzleContent, col: number, row: number) => {
  const cell = c.grid.cells[row][col];
  return cell.kind === 'active' ? cell.letter : 'black';
};

describe('24-S4-1 applying operations committed elsewhere', () => {
  it('applies the next versions in order to the confirmed state, without mutating it', () => {
    const box = outbox();
    const { outbox: next, settled, diverged } = applyCommitted(box, [remote(write(0, 1, 'D'), 5), remote(write(1, 1, 'O'), 6)]);
    expect(diverged).toBe(false);
    expect(settled).toEqual([]);
    expect(next.confirmed.version).toBe(6);
    expect(letterAt(next.confirmed.content, 0, 1)).toBe('D');
    expect(letterAt(next.confirmed.content, 1, 1)).toBe('O');
    expect(letterAt(box.confirmed.content, 0, 1)).toBeNull();
    expect(box.confirmed.version).toBe(4);
  });

  it('skips versions it already holds and stops at a gap', () => {
    const box = outbox();
    const { outbox: next } = applyCommitted(box, [
      remote(write(0, 1, 'X'), 4), remote(write(0, 2, 'Y'), 5), remote(write(0, 3, 'Z'), 7),
    ]);
    expect(next.confirmed.version).toBe(5);
    expect(letterAt(next.confirmed.content, 0, 1)).toBeNull();
    expect(letterAt(next.confirmed.content, 0, 2)).toBe('Y');
    expect(letterAt(next.confirmed.content, 0, 3)).toBeNull();
    expect(applyCommitted(box, []).outbox).toBe(box);
  });

  it('keeps pending operations on top: the projection shows them over the remote change', () => {
    const [box] = add(outbox(), write(0, 1, 'M'));
    const { outbox: next } = applyCommitted(box, [remote(write(0, 1, 'J'), 5), remote(write(4, 4, 'K'), 6)]);
    expect(next.pending).toHaveLength(1);
    expect(letterAt(next.confirmed.content, 0, 1)).toBe('J');
    const shown = projectOutbox(next).content;
    expect(letterAt(shown, 0, 1)).toBe('M');
    expect(letterAt(shown, 4, 4)).toBe('K');
  });

  it("this tab's own operation in the log is applied once, settled and never sent again", () => {
    const [first, mine] = add(outbox(), write(3, 0, 'S'));
    const [box, later] = add(first, write(4, 0, 'E'));
    const committed = { ...mine, version: 6 } as CommittedOperation;
    const { outbox: next, settled } = applyCommitted(box, [remote(write(0, 4, 'R'), 5), committed]);
    expect(settled).toEqual([{ opId: mine.opId, version: 6 }]);
    expect(next.pending.map((op) => op.opId)).toEqual([later.opId]);
    expect(next.confirmed.version).toBe(6);
    expect(letterAt(next.confirmed.content, 3, 0)).toBe('S');
    // Its answer arriving afterwards changes nothing.
    expect(settle(next, mine.opId, { status: 'accepted', version: 6 })).toBe(next);
  });

  it('follows a Start Over and Enter Hints committed elsewhere: their epoch and phase; pending work of the old epoch is left out', () => {
    const [box] = add(outbox(), write(4, 4, 'Q'));
    const { outbox: reset } = applyCommitted(box, [remote({ kind: 'startOver', keepLockedWords: false }, 5)]);
    expect(reset.confirmed.resetEpoch).toBe(1);
    expect(letterAt(reset.confirmed.content, 0, 0)).toBeNull();
    expect(letterAt(projectOutbox(reset).content, 4, 4)).toBeNull();
    expect(projectOutbox(reset).resetEpoch).toBe(1);

    const full = content(letters(blank, [[0, 0, 'A'], [1, 0, 'B'], [0, 1, 'C'], [1, 1, 'D']]));
    const { outbox: hinted } = applyCommitted(outbox(full), [remote({ kind: 'enterHints' }, 5)]);
    expect(hinted.confirmed.content.phase).toBe('hints');
    expect(letterAt(hinted.confirmed.content, 4, 4)).toBe('black');
    expect(Object.keys(hinted.confirmed.content.hints).length).toBeGreaterThan(0);
  });

  it('reports a divergence (an operation that does not fit) and stops before it', () => {
    const box = outbox();
    const { outbox: next, diverged } = applyCommitted(box, [
      remote(write(0, 1, 'D'), 5), remote({ kind: 'hint', key: '1-across', text: 'Build has no hints' }, 6),
    ]);
    expect(diverged).toBe(true);
    expect(next.confirmed.version).toBe(5);
  });
});

describe('24-S4-2 acceptances ahead of the confirmed state, and the snapshot', () => {
  it('an acceptance past the next version is kept as acknowledged: shown, not sent, applied once catching up reaches it', () => {
    const [box, mine] = add(outbox(), write(3, 0, 'S'));
    const settled = settle(box, mine.opId, { status: 'accepted', version: 7 });
    expect(settled.pending).toEqual([]);
    expect(settled.confirmed).toBe(box.confirmed);
    expect(settled.acknowledged?.map((op) => [op.opId, op.version])).toEqual([[mine.opId, 7]]);
    expect(letterAt(projectOutbox(settled).content, 3, 0)).toBe('S');

    const caught = applyCommitted(settled, [
      remote(write(3, 0, 'X'), 5), remote(write(0, 4, 'Y'), 6), { ...mine, version: 7 } as CommittedOperation,
    ]);
    expect(caught.outbox.acknowledged).toBeUndefined();
    expect(caught.outbox.confirmed.version).toBe(7);
    expect(letterAt(caught.outbox.confirmed.content, 3, 0)).toBe('S');
    expect(letterAt(caught.outbox.confirmed.content, 0, 4)).toBe('Y');
  });

  it('the snapshot replaces an older confirmed state, keeping pending work; an older one changes nothing', () => {
    const [first, mine] = add(outbox(), write(3, 0, 'S'));
    const ahead = settle(first, mine.opId, { status: 'accepted', version: 9 });
    const [box] = add(ahead, write(4, 4, 'P'));
    const stored = content(letters(blank, [[0, 0, 'N'], [3, 0, 'S']]), { title: 'Stored' });
    const next = applySnapshot(box, { content: stored, version: 12, resetEpoch: 0 });
    expect(next.confirmed).toEqual({ content: stored, version: 12, resetEpoch: 0 });
    expect(next.acknowledged).toBeUndefined();
    expect(next.pending).toEqual(box.pending);
    expect(letterAt(projectOutbox(next).content, 4, 4)).toBe('P');
    expect(letterAt(projectOutbox(next).content, 0, 0)).toBe('N');
    expect(applySnapshot(box, { content: stored, version: 4, resetEpoch: 0 })).toBe(box);
    expect(applySnapshot(box, { content: stored, version: 8, resetEpoch: 0 }).acknowledged).toHaveLength(1);
  });

  it('rebasing the view over a remote change keeps the draft and takes the rest', () => {
    const before = content(cat);
    const view = content(letters(cat, [[0, 1, 'D']]));
    const after = content(letters(cat, [[0, 0, 'B'], [0, 1, 'Z']]));
    const shown = rebaseView(before, view, after);
    expect(letterAt(shown, 0, 0)).toBe('B');
    expect(letterAt(shown, 0, 1)).toBe('D');
    expect(cellWrites(after.grid, shown.grid)).toEqual([{ col: 0, row: 1, value: 'D' }]);
  });
});

// A server that commits as the commit path does (validate against the
// current state, apply, advance the version by one) and keeps a log.
function server(initial: PuzzleContent) {
  let state: PuzzleState = { ...initial, resetEpoch: 0, published: false };
  const log: CommittedOperation[] = [];
  const seen = new Map<string, { status: 'accepted'; version: number } | { status: 'refused' }>();
  return {
    get state() { return state; },
    get version() { return log.length; },
    commit(op: Operation) {
      const known = seen.get(op.opId);
      if (known) return known;
      const result = evaluateOperation(state, op, { isOwner: true });
      if (!result.ok) {
        seen.set(op.opId, { status: 'refused' });
        return { status: 'refused' as const };
      }
      state = { ...state, ...applyOperation(state, op).content, resetEpoch: epochAfter(state.resetEpoch, op) };
      log.push({ ...op, version: log.length + 1 });
      const answer = { status: 'accepted' as const, version: log.length };
      seen.set(op.opId, answer);
      return answer;
    },
    since(version: number) { return log.slice(version); },
  };
}

function prng(seed: number) {
  let t = seed >>> 0;
  return () => {
    t = (t + 0x6d2b79f5) >>> 0;
    let r = Math.imul(t ^ (t >>> 15), 1 | t);
    r = (r + Math.imul(r ^ (r >>> 7), 61 | r)) ^ r;
    return ((r ^ (r >>> 14)) >>> 0) / 4294967296;
  };
}

describe('24-S4-3 tabs that poll converge', () => {
  it.each([1, 2, 3, 4, 5, 6, 7, 8])('seed %i: every tab ends showing the server’s puzzle', (seed) => {
    const random = prng(seed);
    const pick = <T,>(list: readonly T[]) => list[Math.floor(random() * list.length)];
    const srv = server(content(cat));
    const tabs = Array.from({ length: 3 }, (_, index) => ({ id: `tab-${index}`, box: outbox(content(cat), 0) }));
    let n = 0;
    for (let step = 0; step < 300; step++) {
      const tab = pick(tabs);
      const roll = random();
      if (roll < 0.4) {
        const body: OperationBody = random() < 0.05
          ? { kind: 'startOver', keepLockedWords: false }
          : random() < 0.1 ? { kind: 'title', title: `T${step}` }
          : write(Math.floor(random() * 5), Math.floor(random() * 5), pick(['A', 'B', 'C', null]));
        const op = makeOperation(tab.box, body, { opId: `s${seed}-${++n}`, puzzleId: 'p', clientId: tab.id });
        tab.box = enqueue(tab.box, op);
      } else if (roll < 0.75 && tab.box.pending.length > 0) {
        // The head is sent; its answer is sometimes lost (it stays pending, and is re-sent).
        const head = tab.box.pending[0];
        const answer = srv.commit(head);
        if (random() < 0.8) tab.box = settle(tab.box, head.opId, answer.status === 'accepted' ? answer : { status: 'refused', code: 'epoch' });
      } else {
        const result = applyCommitted(tab.box, srv.since(tab.box.confirmed.version));
        expect(result.diverged).toBe(false);
        tab.box = result.outbox;
      }
    }
    // Drain: send everything, then catch up.
    for (const tab of tabs) {
      while (tab.box.pending.length > 0) {
        const head = tab.box.pending[0];
        const answer = srv.commit(head);
        tab.box = settle(tab.box, head.opId, answer.status === 'accepted' ? answer : { status: 'refused', code: 'epoch' });
      }
    }
    for (const tab of tabs) {
      tab.box = applyCommitted(tab.box, srv.since(tab.box.confirmed.version)).outbox;
      expect(tab.box.confirmed.version).toBe(srv.version);
      expect(tab.box.acknowledged).toBeUndefined();
      const { grid, hints, title, phase, resetEpoch } = srv.state;
      const stored = { grid, hints, title, phase };
      expect(tab.box.confirmed.content).toEqual(stored);
      expect(tab.box.confirmed.resetEpoch).toBe(resetEpoch);
      expect(projectOutbox(tab.box).content).toEqual(stored);
    }
  });
});
